mapper.select:
SELECT 
	F.TABLE_ID
FROM BOK_FEE_TABLE_SET F
WHERE F.PS = #{ps}
    AND F.FINPROD_TYPE = #{finprodType}
    AND F.FEE_TYPE_ID = #{feeType}

select sum(nvl(decode(d.is_clean,'N',d.trade_amt,pd.theory_int),0))
from trd_product_deal d
left join pa_trd_product_deal pd
on d.trade_id=pd.trade_id
where d.trade_status='01' and d.Is_Cancel='N' and d.finprod_id= #{finprodId} and d.finprod_type=#{finprodType}
and d.settle_date　>= #{mdate,jdbcType=DATE} and d.mdate< #{mdate,jdbcType=DATE}
